    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static void Seam(BackupEngine engine,string property,object value)=>typeof(BackupEngine).GetProperty(property,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(engine,value);
    static WorkHistoryDocument History(MainWindow w)=>Get<WorkHistoryDocument>(w,"workHistory");
    static void Refresh(MainWindow w)=>Wait((Task)Call(w,"RefreshHistoryAsync")!);
    static (MainWindow Window,Package Game,BackupEngine Engine,BackupJob Job) Backed(string dir)
    {var w=Window(dir,out var p);LibraryStore.EnsureIdentity(p.Source,p.Id);p.Registered=true;var engine=new BackupEngine(Path.Combine(dir,"backups"));var job=Task.Run(()=>engine.CreateAsync(p,[])).GetAwaiter().GetResult();return(w,p,engine,job);}
    static void SaveScreen(Window window,string filename,double width=0,double height=0){width=width>0?width:window.Width;height=height>0?height:window.Height;if(window is AppDialog){var dialog=(AppDialog)window;var body=(FrameworkElement)dialog.BodyScroll.Content;body.Measure(new Size(width-74,double.PositiveInfinity));dialog.ActionPanel.Measure(new Size(width-56,double.PositiveInfinity));height=Math.Clamp(body.DesiredSize.Height+dialog.ActionPanel.DesiredSize.Height+64,280,720);}Layout(window,width,height,filename);}
    static void SaveContent(MainWindow w,string filename){Call(w,"SetPage","jobs");Call(w,"PaintHistory");var root=(FrameworkElement)w.Content;root.Measure(new Size(1000,840));root.Arrange(new Rect(0,0,1000,840));root.UpdateLayout();var panel=(FrameworkElement)w.FindName("JobsPanel");panel.Measure(new Size(1000,740));panel.Arrange(new Rect(0,0,1000,740));panel.UpdateLayout();var bitmap=new RenderTargetBitmap(1000,740,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var d=bg.RenderOpen())d.DrawRectangle(w.Background,null,new Rect(0,0,1000,740));bitmap.Render(bg);bitmap.Render(panel);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(filename);png.Save(output);}
    static void CaptureModal(Action invoke,string filename)
    {Application.Current.Dispatcher.BeginInvoke(new Action(()=>{var dialog=Application.Current.Windows.OfType<AppDialog>().Last();SaveScreen(dialog,filename,600,500);dialog.Close();}),DispatcherPriority.Background);invoke();}
    static void Refuse(Action invoke){try{invoke();}catch(Exception e)when(e is IOException or InvalidDataException or UnauthorizedAccessException){return;}throw new Exception("Expected refusal");}
    [STAThread]static int Main(string[] args)
    {
        if(args[0]=="--crash")
        {var engine=new BackupEngine(Path.Combine(args[1],"backups"));Seam(engine,"ForceCopyMove",true);Seam(engine,"Checkpoint",(Action<string>)(point=>{if(point=="move-before-capture"){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}}));var job=engine.ListJobs(false).Single();Task.Run(()=>engine.MoveAsync(job.Id,Path.Combine(args[1],"target","Moved"))).GetAwaiter().GetResult();return 0;}
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var gallery=Path.GetFullPath(args[2]);Directory.CreateDirectory(gallery);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("old-backup-root-remains-in-history",dir=>{var f=Backed(dir);try{Refresh(f.Window);Check(History(f.Window).Records.Any(r=>r.JobId==f.Job.Id),"Initial backup missing");Wait((Task)Call(f.Window,"ChangeBackupRootAsync",Path.Combine(dir,"new-backups"))!);Check(History(f.Window).Records.Any(r=>r.JobId==f.Job.Id&&r.Root==f.Engine.Root),"Old history lost after root change");Check(Directory.Exists(f.Engine.Payload(f.Job)),"Changing root moved or deleted backup");}finally{Close(f.Window);}});
        Test("offline-backup-preserved-and-reconnects",dir=>{var f=Backed(dir);try{Refresh(f.Window);var held=Path.Combine(dir,"detached-backups");Directory.Move(f.Engine.Root,held);Refresh(f.Window);var record=History(f.Window).Records.Single(r=>r.JobId==f.Job.Id);Check(record.Availability=="Offline"&&record.State=="Completed","Offline backup treated as deleted");SaveContent(f.Window,Path.Combine(gallery,"01-backup-offline.png"));Wait((Task)Call(f.Window,"ReconnectHistoryRootAsync",record,held)!);Check(History(f.Window).Records.Single(r=>r.JobId==f.Job.Id).Root==held&&History(f.Window).Records.Single(r=>r.JobId==f.Job.Id).Availability=="Connected","Verified backup location not adopted");Check(File.Exists(Path.Combine(f.Game.Source,"Game.exe")),"Reconnect touched original game");}finally{Close(f.Window);}});
        Test("wrong-backup-folder-refused",dir=>{var f=Backed(dir);try{Refresh(f.Window);var record=History(f.Window).Records.Single(r=>r.JobId==f.Job.Id);Refuse(()=>new WorkHistoryStore(Path.Combine(dir,"data","work-history.json")).Reconnect(record,Path.Combine(dir,"wrong")));Check(History(f.Window).Records.Single(r=>r.JobId==f.Job.Id).Root==f.Engine.Root,"Wrong root silently adopted");}finally{Close(f.Window);}});
        Test("missing-manifest-is-not-deletion",dir=>{var f=Backed(dir);try{Refresh(f.Window);var manifest=Path.Combine(f.Engine.Root,f.Job.Id,"manifest.json");File.Move(manifest,manifest+".held");if(File.Exists(manifest+".bak"))File.Move(manifest+".bak",manifest+".bak.held");Refresh(f.Window);Check(History(f.Window).Records.Any(r=>r.JobId==f.Job.Id&&r.State!="Deleted"),"Missing record treated as deleted");SaveContent(f.Window,Path.Combine(gallery,"02-record-missing.png"));}finally{Close(f.Window);}});
        Test("corrupt-index-is-preserved",dir=>{var f=Backed(dir);try{Refresh(f.Window);var file=Path.Combine(dir,"data","work-history.json");File.WriteAllText(file,"broken primary");File.WriteAllText(file+".bak","broken backup");Refresh(f.Window);Check(File.ReadAllText(file)=="broken primary"&&File.ReadAllText(file+".bak")=="broken backup","Corrupt index overwritten");Check(Directory.Exists(f.Engine.Payload(f.Job)),"Index failure deleted backup");int calls=0;Set(f.Window,"intakeInProgress",true);Func<BackupEngine,IProgress<BackupProgress>,CancellationToken,Task> action=(e,p,t)=>{calls++;return Task.CompletedTask;};Wait((Task)Call(f.Window,"RunFileOperation","백업 검증",action,null,"가상 게임",f.Engine,false)!);Check(calls==0&&Get<OperationStatus>(f.Window,"operationStatus").Finished&&Get<OperationStatus>(f.Window,"operationStatus").Failed==1,"Corrupt index started files or left an endless progress state");Set(f.Window,"intakeInProgress",false);SaveContent(f.Window,Path.Combine(gallery,"03-index-error.png"));}finally{Close(f.Window);}});
        Test("history-loading-does-not-block-dispatcher",dir=>{var w=Window(dir,out _);try{var store=new WorkHistoryStore(Path.Combine(dir,"data","work-history.json"));var now=DateTime.UtcNow;store.Save(new(){Roots=[Path.Combine(dir,"backups")],Records=Enumerable.Range(0,2400).Select(i=>new WorkRecord{Root=Path.Combine(dir,"backups"),JobId=Guid.NewGuid().ToString("N"),Title="가상 기록 "+i,GameId=Guid.NewGuid().ToString("N"),State="Completed",UpdatedUtc=now,Availability="Connected"}).ToList()});var main=Environment.CurrentManagedThreadId;typeof(WorkHistoryStore).GetProperty("InspectingRoot",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(store,(Action<string>)(_=>{Check(Environment.CurrentManagedThreadId!=main,"Root inspected on UI thread");Thread.Sleep(300);}));Set(w,"historyFactory",(Func<WorkHistoryStore>)(()=>store));var watch=Stopwatch.StartNew();Call(w,"RenderBackupJobs");Check(watch.ElapsedMilliseconds<300,"History render blocked on disk");var task=(Task)Call(w,"RefreshHistoryAsync")!;bool responded=false;Application.Current.Dispatcher.BeginInvoke(new Action(()=>responded=true),DispatcherPriority.Background);Wait(task);Check(responded&&History(w).Records.Count==2400,"Dispatcher failed during slow record load");Check(Logical((DependencyObject)w.FindName("JobsContent")).OfType<Border>().Count()<100,"Unbounded card construction");}finally{Close(w);}});
        Test("preflight-access-denial-before-registration",dir=>{var w=Window(dir,out var p);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);LibraryStore.EnsureIdentity(p.Source,p.Id);timer.Tick+=(_,_)=>{foreach(var d in Application.Current.Windows.OfType<AppDialog>().ToList()){SaveScreen(d,Path.Combine(gallery,"04-registration-denied.png"));d.Close();}};timer.Start();using(var held=File.Open(Path.Combine(p.Source,LibraryStore.MarkerName),FileMode.Open,FileAccess.Read,FileShare.None))Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,new(){p}),Path.Combine(dir,"library"))!);Check(p.Registered!=true&&p.ReviewState=="identity"&&Get<List<IntakeResult>>(w,"lastIntakeResults").Count==0&&File.Exists(Path.Combine(p.Source,"Game.exe")),"Denied preflight changed registration or files");}finally{timer.Stop();Close(w);}});
        Test("physical-move-failure-keeps-registration-and-backup-visible",dir=>{var w=Window(dir,out var p);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);Set(w,"backupEngineFactory",(Func<BackupEngine>)(()=>{var e=new BackupEngine(Path.Combine(dir,"backups"));Seam(e,"ForceCopyMove",true);Seam(e,"Checkpoint",(Action<string>)(point=>{if(point=="move-before-capture")throw new IOException("가상 장치 쓰기 오류");}));return e;}));timer.Tick+=(_,_)=>{foreach(var d in Application.Current.Windows.OfType<AppDialog>().ToList()){SaveScreen(d,Path.Combine(gallery,"05-move-stop-choice.png"),600,580);d.Close();}};timer.Start();var plan=Plan(w,new(){p});plan.SetAll(true);Wait((Task)Call(w,"ExecuteIntakeAsync",plan,Path.Combine(dir,"library"))!);timer.Stop();var row=Get<List<IntakeResult>>(w,"lastIntakeResults").Single();Check(row.Registration=="등록됨"&&!row.Success&&row.Backup=="생성 완료","Partial success facts lost");var dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{row})!;SaveScreen(dialog,Path.Combine(gallery,"06-move-failed-result.png"));dialog.Close();}finally{timer.Stop();Close(w);}});
        Test("save-failure-after-real-move-and-direct-retry",dir=>{var w=Window(dir,out var p);try{Set(w,"identityNoticeAccepted",true);Set(w,"suppressIntakeResult",true);var original=p.Source;Wait((Task)Call(w,"ExecuteMoveListAsync",new MoveSelection(new[]{p},Get<List<Package>>(w,"packages")).Items(Path.Combine(dir,"library")),Path.Combine(dir,"library"))!);Refresh(w);var file=Get<WorkspaceStore>(w,"workspaceStore").FilePath;p.Alias="저장 실패 가상 게임";bool saved;using(var held=File.Open(file,FileMode.Open,FileAccess.ReadWrite,FileShare.None))saved=(bool)Call(w,"FlushWorkspace")!;Check(!saved,"Fixture did not deny save");var row=IntakeEvidence.Inspect(new(p.Id,"가상 게임","등록 정보 저장 필요"){Source=original,Destination=p.Source,Registration="등록됨",Saved=false},History(w).Records);Check(row.Location.StartsWith("보관함으로 이동됨")&&row.Solution=="Save"&&!row.Success,"Save failure confused with unmoved files");var dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{row})!;SaveScreen(dialog,Path.Combine(gallery,"07-moved-save-failed.png"));dialog.Close();Wait((Task)Call(w,"SolveIntakeResultAsync",row,new List<IntakeResult>{row})!);Check(Get<List<IntakeResult>>(w,"lastIntakeResults").Single().Success,"Direct save retry did not recover");}finally{Close(w);}});
        Test("interrupted-move-result-resumes-from-primary-action",dir=>{var f=Backed(dir);try{var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true};start.ArgumentList.Add("--crash");start.ArgumentList.Add(dir);using(var child=Process.Start(start)!){var ready=child.StandardOutput.ReadLineAsync();Check(ready.Wait(15000)&&ready.Result=="READY","Crash fixture did not reach checkpoint");child.Kill(true);child.WaitForExit();}f.Engine.ListMoves();Refresh(f.Window);var move=History(f.Window).Records.Single(r=>r.Kind=="Move");var row=IntakeEvidence.Inspect(new(f.Game.Id,"가상 게임","중단됨"){Source=f.Game.Source,Destination=move.Destination,Registration="등록됨"},History(f.Window).Records);Check(row.Solution=="Resume","Interrupted move not directly resumable");var dialog=(Window)Call(f.Window,"BuildIntakeResult",new List<IntakeResult>{row})!;SaveScreen(dialog,Path.Combine(gallery,"08-interrupted-resume.png"));dialog.Close();Set(f.Window,"suppressIntakeResult",true);Wait((Task)Call(f.Window,"SolveIntakeResultAsync",row,new List<IntakeResult>{row})!);Check(Get<List<IntakeResult>>(f.Window,"lastIntakeResults").Single().Success,"Primary resume did not finish move");}finally{Close(f.Window);}});
        Test("missing-game-and-name-collision-actions",dir=>{var w=Window(dir,out var p);try{var original=p.Source;Directory.Move(original,Path.Combine(dir,"held-game"));var row=IntakeEvidence.Inspect(new(p.Id,"가상 게임","위치 확인 필요"){Source=original,Registration="등록됨"},[]);Check(row.Solution=="Locate","Missing game has no direct folder action");var dialog=(Window)Call(w,"BuildIntakeResult",new List<IntakeResult>{row})!;SaveScreen(dialog,Path.Combine(gallery,"09-game-missing.png"));dialog.Close();Directory.Move(Path.Combine(dir,"held-game"),original);var target=Path.Combine(dir,"target","Taken");Directory.CreateDirectory(target);var collision=IntakeEvidence.Inspect(new(p.Id,"가상 게임","이동하지 않음"){Source=original,Destination=target,Registration="등록됨"},[]);Check(collision.Solution=="Name","Collision not routed to name edit");dialog=(Window)Call(w,"BuildDestinationNameFix",collision)!;SaveScreen(dialog,Path.Combine(gallery,"10-name-collision.png"),620,430);Check(!FindButton(dialog,"이동 설정 확인").IsEnabled,"Colliding target accepted");var box=Logical((DependencyObject)dialog.Content).OfType<TextBox>().Single();box.Text="FreeName";Check(FindButton(dialog,"이동 설정 확인").IsEnabled,"Valid replacement rejected");dialog.Close();}finally{Close(w);}});
        Test("common-error-dialog-source-catalog",dir=>{var catalog=JsonSerializer.Deserialize<List<Dictionary<string,string>>>(File.ReadAllText(args[3]))!;int number=0;foreach(var item in catalog){var dialog=new AppDialog(null,item["title"],item["message"],[new("close","확인",true)],"close",details:item["kind"]=="ErrorInfo"?"가상 데이터로 재현한 오류입니다. 실제 개인 파일과 경로는 포함하지 않습니다.":null,tone:item["kind"]=="ErrorInfo"?DialogTone.Warning:DialogTone.Information);SaveScreen(dialog,Path.Combine(gallery,$"common-{++number:D3}.png"),600,500);Check(dialog.ActionButtons.All(b=>b.Focusable),"Error button not focusable");dialog.Close();}Check(number>40,"Error screen catalog incomplete");});
        Test("launch-and-save-warning-variants",dir=>{var w=Window(dir,out var p);try{int i=0;foreach(var problem in Enum.GetValues<LaunchProblem>().Where(p=>p is not (LaunchProblem.None or LaunchProblem.Setup))){var state=GameLaunch.State(problem);CaptureModal(()=>Call(w,"ShowLaunchProblem",p,state,"가상 오류 원인입니다."),Path.Combine(gallery,$"launch-{++i:D2}.png"));}Call(w,"SaveIssue",new WorkspaceSaveIssue("SAVE-FIXTURE","변경 내용을 저장하지 못했습니다. 폴더의 쓰기 권한을 확인하세요."),"가상 저장 오류");CaptureModal(()=>Call(w,"ShowWorkspaceSaveIssue"),Path.Combine(gallery,"11-save-problem.png"));}finally{Close(w);}});
