        Test("concurrent-root-updates-keep-both-locations",dir=>{var file=Path.Combine(dir,"index.json");var a=Path.Combine(dir,"A");var b=Path.Combine(dir,"B");Parallel.Invoke(()=>new WorkHistoryStore(file).Register(new[]{a}),()=>new WorkHistoryStore(file).Register(new[]{b}),()=>new WorkHistoryStore(file).Refresh([]));var doc=new WorkHistoryStore(file).Load();Check(doc.Roots.Contains(a)&&doc.Roots.Contains(b),"Concurrent refresh lost registered root");});
        Test("previous-location-can-be-added-without-changing-new-backup-root",dir=>{var f=Backed(dir);try{var current=Path.Combine(dir,"new-backups");Set(f.Window,"backupStorageRoot",current);Wait((Task)Call(f.Window,"AddHistoryRootAsync",f.Engine.Root)!);Check(Get<string>(f.Window,"backupStorageRoot")==current&&History(f.Window).Records.Any(r=>r.JobId==f.Job.Id),"Adding old location changed current destination or missed backup");}finally{Close(f.Window);}});
        Test("old-root-actions-use-the-original-backup-and-move-records",dir=>{var w=Window(dir,out var p);try{var original=p.Source;Wait((Task)Call(w,"ExecuteMoveListAsync",new MoveSelection(new[]{p},Get<List<Package>>(w,"packages")).Items(Path.Combine(dir,"library")),Path.Combine(dir,"library"))!);var old=Path.Combine(dir,"backups");var next=Path.Combine(dir,"new-backups");Wait((Task)Call(w,"ChangeBackupRootAsync",next)!);var backup=History(w).Records.Single(r=>r.Kind=="Backup");Wait((Task)Call(w,"RunHistoryBackupAsync",backup,"verify")!);var move=History(w).Records.Single(r=>r.Kind=="Move");Wait((Task)Call(w,"RunHistoryMoveAsync",move,true)!);Check(p.Source==original&&File.Exists(Path.Combine(original,"Game.exe")),"Old-root undo used the new backup location");Check(Directory.Exists(old)&&!Directory.Exists(next),"Old-root action created or used new backup payload");}finally{Close(w);}});
        Test("same-location-with-trailing-slash-is-not-duplicated",dir=>{var f=Backed(dir);try{var store=new WorkHistoryStore(Path.Combine(dir,"index.json"));store.Refresh(new[]{f.Engine.Root+Path.DirectorySeparatorChar});var doc=store.Refresh(new[]{f.Engine.Root});Check(doc.Roots.Count==1&&doc.Records.Count(r=>r.JobId==f.Job.Id)==1,"Same directory appeared twice");}finally{Close(f.Window);}});
        Test("double-click-during-history-preparation-starts-only-one-operation",dir=>{var w=Window(dir,out _);try{int count=0;Func<BackupEngine,IProgress<BackupProgress>,CancellationToken,Task> action=async(e,p,t)=>{Interlocked.Increment(ref count);await Task.Delay(30,t);};var a=(Task)Call(w,"RunFileOperation","백업 검증",action,null,"가상 게임",new BackupEngine(Path.Combine(dir,"backups")),false)!;var b=(Task)Call(w,"RunFileOperation","백업 검증",action,null,"가상 게임",new BackupEngine(Path.Combine(dir,"backups")),false)!;Wait(Task.WhenAll(a,b));Check(count==1,"Preparation allowed overlapping operations");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
